[Authorize]
public class DuelHub(MatchmakingService matchmaking) : Hub
{
    public async Task FindDuel()
    {
        var opponentId = matchmaking.Join(Context.UserIdentifier!);
        if (opponentId is not null)
            await Clients.Users(Context.UserIdentifier!, opponentId).SendAsync("MatchFound");
    }
}

public class MatchmakingService
{
    private static readonly ConcurrentQueue<string> Waiting = new();

    public string? Join(string userId)
    {
        if (Waiting.TryDequeue(out var opponentId))
            return opponentId;

        Waiting.Enqueue(userId);
        return null;
    }
}

public async Task FinalizeAsync(Duel duel)
{
    duel.Status = DuelStatus.Finished;
    db.Outbox.Add(new DuelFinished(duel.Id, duel.PlayerIds, duel.XpByPlayer));
    await db.SaveChangesAsync();
}

public class QueueConsumer(IQueue queue, DuelFinishedHandler handler)
{
    public async Task RunAsync(CancellationToken ct)
    {
        await foreach (var delivery in queue.ReadAsync<DuelFinished>(ct))
        {
            await handler.HandleAsync(delivery.Message);
            // Acknowledge only after the work is saved, so a crash means redelivery instead of loss
            await delivery.AckAsync();
        }
    }
}

public class DuelFinishedHandler(AppDbContext db)
{
    public async Task HandleAsync(DuelFinished message)
    {
        foreach (var playerId in message.PlayerIds)
        {
            var player = await db.Players.FindAsync(playerId);
            player!.Xp += message.XpByPlayer[playerId];
        }
        await db.SaveChangesAsync();
    }
}

