[HttpPost("avatar")]
public async Task<IActionResult> UploadAvatar(IFormFile file)
{
    var fileName = $"{User.GetUserId()}.png";
    await using var stream = System.IO.File.Create(Path.Combine("wwwroot/avatars", fileName));
    await file.CopyToAsync(stream);
    return Ok(new { url = $"/avatars/{fileName}" });
}

